CREATE TABLE forms (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  list_id uuid NOT NULL /* id -> hierarchy.lists */,
  name text NOT NULL,
  description text,
  access text NOT NULL DEFAULT 'internal' CHECK (access IN ('internal','authenticated','public')),
  captcha boolean NOT NULL DEFAULT true,
  submission_cap integer, closes_at timestamptz,
  confirmation_message text, redirect_url text, email_receipt boolean NOT NULL DEFAULT false,
  owner_id uuid /* id -> identity.users */,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed','archived')),
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE TABLE form_questions (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  form_id uuid NOT NULL REFERENCES forms(id) ON DELETE CASCADE,
  key text NOT NULL,
  label text NOT NULL,
  question_type text NOT NULL CHECK (question_type IN ('short_text','long_text','number','date','dropdown','multi_select','checkbox','rating','file','user','email','phone')),
  options jsonb,
  required boolean NOT NULL DEFAULT false,
  map_to text NOT NULL DEFAULT 'custom_field' CHECK (map_to IN ('title','description','custom_field','priority','due_at','assignee','tag')),
  custom_field_id uuid /* id -> tasks.custom_fields */,
  visible_when jsonb,                                       -- conditional logic over earlier answers
  page_no smallint NOT NULL DEFAULT 1,
  position text NOT NULL COLLATE "C",
  UNIQUE (form_id, key),
  CHECK (map_to <> 'custom_field' OR custom_field_id IS NOT NULL)
);

CREATE TABLE form_routing_rules (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  form_id uuid NOT NULL REFERENCES forms(id) ON DELETE CASCADE,
  priority_order integer NOT NULL,
  condition jsonb NOT NULL,
  target_list_id uuid /* id -> hierarchy.lists */,
  assignee_id uuid /* id -> identity.users */, group_id uuid /* id -> access.user_groups */,
  set_priority smallint CHECK (set_priority BETWEEN 1 AND 4),
  template_id uuid /* id -> tasks.templates */
);

CREATE TABLE form_submissions (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  id uuid NOT NULL,
  form_id uuid NOT NULL REFERENCES forms(id),
  payload jsonb NOT NULL,                                   -- raw answers, kept even if mapping fails (BRL-027)
  submitter_user_id uuid /* id -> identity.users */,
  submitter_email text,
  status text NOT NULL DEFAULT 'stored' CHECK (status IN ('stored','converted','failed')),
  task_id uuid /* id -> tasks.tasks */,
  error text,
  submitted_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, id)
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('form_submissions', 8);

CREATE INDEX form_submissions_form ON form_submissions (workspace_id, form_id, submitted_at DESC);

CREATE INDEX form_submissions_failed ON form_submissions (workspace_id, status) WHERE status <> 'converted';
